        { niva: 2, typ: 'ordna', text: 'Ordna högtiderna i kyrkoåret. Kyrkoåret börjar med advent.', items: ['Advent', 'Jul', 'Fastan', 'Påsk', 'Pingst'], etiketter: ['Först', 'Sist'], ledtrad: 'Advent kommer före jul. Fastan kommer före påsk.', losning: ['**Advent** → **jul** → **fastan** → **påsk** → **pingst**.'] },
        { niva: 2, typ: 'ordna', text: 'Ordna dagarna i påskens berättelse, så som det står i Bibeln.', items: ['Palmsöndagen – Jesus rider in i Jerusalem', 'Skärtorsdagen – Jesus äter sista måltiden', 'Långfredagen – Jesus dör på korset', 'Påskdagen – Jesus uppstår'], etiketter: ['Först', 'Sist'], ledtrad: 'Påskveckan börjar med palmsöndagen och slutar med påskdagen.', losning: ['**Palmsöndagen** → **skärtorsdagen** → **långfredagen** → **påskdagen**.', 'Veckan före påskdagen kallas **stilla veckan**.'] },
        { niva: 2, typ: 'val', text: 'Vad firar kristna på pingsten?', alt: ['Att den heliga Anden kom till lärjungarna', 'Att Jesus föddes', 'Att Jesus dog', 'Att de vise männen kom till Jesus'], ratt: 0, ledtrad: 'Pingsten kommer femtio dagar efter påsk.', losning: ['På **pingsten** kom enligt Bibeln **den heliga Anden** till lärjungarna.', 'Därför brukar pingsten kallas **kyrkans födelsedag**.'] },
        { niva: 2, typ: 'val', text: 'Vad händer vid ett dop?', alt: ['Den som döps får vatten öst över sig och blir en del av den kristna gemenskapen', 'Man äter bröd och dricker vin', 'Man fastar en hel dag', 'Man reser till Jerusalem'], ratt: 0, ledtrad: 'Det behövs vatten.', losning: ['Vid **dopet** öser prästen **vatten** över huvudet på den som döps. I vissa kyrkor doppas man helt i vattnet.', 'I Svenska kyrkan döps oftast **små barn**.'] },
        { niva: 2, typ: 'val', text: 'Vad kallas skålen med vatten som används vid dop i kyrkan?', alt: ['Dopfunt', 'Altare', 'Predikstol', 'Mihrab'], ratt: 0, ledtrad: 'Ordet börjar med samma ord som det man gör där.', losning: ['I kyrkan finns **dopfunten** för dopet, **altaret** längst fram där nattvarden firas och **predikstolen**, där prästen kan predika.'] },
        { niva: 2, typ: 'val', text: 'Vad är nattvarden?', alt: ['En måltid med bröd och vin till minne av Jesus sista måltid', 'En gudstjänst mitt i natten', 'En bön innan man somnar', 'En högtid i november'], ratt: 0, ledtrad: 'Den är till minne av vad Jesus gjorde på skärtorsdagen.', losning: ['Vid **nattvarden** delar man **bröd och vin** eller saft.', 'Det är till minne av den **sista måltiden**, som Jesus åt med lärjungarna innan han dog. Många kristna tror att Jesus är närvarande vid nattvarden.'] },
        { niva: 3, typ: 'val', text: 'Vad betyder ordet advent?', alt: ['Ankomst – man väntar på att fira Jesus födelse', 'Ljus', 'Fest', 'Snö'], ratt: 0, ledtrad: 'Man väntar på att något ska komma.', losning: ['**Advent** betyder **ankomst**. Under de fyra söndagarna före jul väntar man på julen, då man firar Jesus födelse.', 'Därför tänder man ett nytt ljus varje adventssöndag.'] },
        { niva: 3, typ: 'val', text: 'Vad kallas tiden före påsk, då en del kristna avstår från något, till exempel godis eller kött?', alt: ['Fastan', 'Advent', 'Ramadan', 'Pingst'], ratt: 0, ledtrad: 'Den börjar dagen efter fettisdagen.', losning: ['Före påsk kommer **fastan**, som varar i 40 dagar. Förr åt man inte kött då, och i dag väljer en del att avstå från något.', '**Fettisdagen**, när man äter semlor, är dagen innan fastan börjar!'] },
        { niva: 3, typ: 'val', text: 'Vad är konfirmation?', alt: ['När unga lär sig mer om den kristna tron och bekräftar sitt dop', 'När man döps som bebis', 'Ett kristet bröllop', 'När man blir präst'], ratt: 0, ledtrad: 'Ordet betyder bekräftelse.', losning: ['Vid **konfirmationen**, oftast när man är runt 14–15 år, lär man sig mer om tron.', 'Ordet betyder **bekräftelse** – man bekräftar sitt dop.'] }
