        { niva: 2, typ: 'val', text: 'Vad betyder halal?', alt: ['Det som är tillåtet enligt islam, till exempel viss mat', 'En muslimsk högtid', 'En bönematta', 'Ett annat ord för moské'], ratt: 0, ledtrad: 'Motsatsen heter haram.', losning: ['**Halal** betyder **tillåtet**. Motsatsen är **haram**, som betyder förbjudet.', 'Enligt islam är till exempel **fläskkött** och **alkohol** haram.'] },
        { niva: 3, typ: 'val', text: 'Vad är Kaba?', alt: ['En kubformad byggnad i Mecka som är islams heligaste plats', 'Ett annat namn för Koranen', 'En muslimsk högtid', 'Ett tempel i Jerusalem'], ratt: 0, ledtrad: 'Kaba betyder ungefär kub.', losning: ['**Kaba** står mitt i den stora moskén i **Mecka**. Muslimer över hela världen vänder sig mot Kaba när de ber.', 'Vid vallfärden går man runt Kaba **sju gånger**.'] },
        { niva: 3, typ: 'val', text: 'Vad kallas nischen i moskéns vägg som visar åt vilket håll Mecka ligger?', alt: ['Mihrab', 'Minaret', 'Altare', 'Kaba'], ratt: 0, ledtrad: 'Minareten är tornet, och Kaba ligger i Mecka.', losning: ['**Mihrab** är nischen som visar riktningen mot Mecka.', 'Bredvid finns ofta **minbar**, en trappa med en talarplats där imamen håller sitt tal på fredagen.'] },
        { niva: 3, typ: 'val', text: 'Vad är en imam?', alt: ['En person som leder bönen i moskén', 'En helig bok', 'En högtid', 'En bönematta'], ratt: 0, ledtrad: 'Det är en person.', losning: ['En **imam** leder bönen och kan undervisa och ge råd. Det liknar lite vad en **präst** gör i en kyrka.'] },
        { niva: 3, typ: 'val', text: 'Vilka är de två största inriktningarna inom islam?', alt: ['Sunni och shia', 'Katoliker och protestanter', 'Ortodoxa och reformerade', 'Imamer och präster'], ratt: 0, ledtrad: 'Stryk först de alternativ som handlar om kristendomen eller om yrken.', losning: ['De flesta muslimer är **sunniter**, och en mindre grupp är **shiiter**.', 'Från början var de oense om vem som skulle leda muslimerna efter Muhammed.'] },
        { niva: 3, typ: 'val', text: 'Vad kallas trosbekännelsen inom islam?', alt: ['Shahada', 'Salat', 'Zakat', 'Hajj'], ratt: 0, ledtrad: 'De andra tre är bönen, allmosan och vallfärden.', losning: ['**Shahada**: "Det finns ingen gud utom Gud, och Muhammed är Guds sändebud."', '**Salat** är bönen, **zakat** är allmosan och **hajj** är vallfärden.'] }
